handlers.reloadSearchGrid:
function reloadSearchGrid(event) {
			var billPartyCode = $("#gs_billPartyCode").val();
			var intCode = $("#gs_intCode").val();

			if($("#financialClient").val().split("-")[1] != "XRO" && billPartyCode != "-1" && intCode == "-1"){
				tryFocusBS($("#gs_intCode"));
				window.parent.showAlert('Document Type is manadatory for searching');
				return false;
			}
			else{
				var retVal = $("#tallyInterfaceTable").jqGrid('setGridParam', {
					datatype : 'json',
					page : 1,
					postData : {
						billPartyCode	:$("#gs_billPartyCode").val(),
						intCode			:$("#gs_intCode").val(),
						key2			:$("#gs_key2").val(),
						status			:$("#gs_status").val(),
						errorDesc		:$("#gs_errorDesc").val(),
						fromUpdDate		:$("#fromUpdDate").val(),
						toUpdDate		:$("#toUpdDate").val(),
						clientId		:$("#gs_clientId").val(),
						finKey			:$("#financialClient").val().split("-")[1],
						finKeyValue		:$("#financialClient").val().split("-")[0], //VE-32865 SE
						REQ_SEARCH_FLAG : true
					},
					url : "jsonTallyInterfaceSearch",
					search : true				
				}).trigger('reloadGrid');
				console.log(retVal);
			}
		}

